void main(List<String> args) {
  final reps = args.isEmpty ? 40 : int.parse(args.first);
  TraceDiagnostics.enabled = true;
  for (final (name, source) in [
    ('locus-miss-2', _lm2),
    ('apatitos-topos', _apat),
  ]) {
    final construction = decodeDocument(
      jsonDecode(source) as Map<String, dynamic>,
    ).construction;
    final locus = construction.objects.whereType<Locus>().single;
    for (var i = 0; i < 5; i++) {
      locus.recompute();
    }
    TraceDiagnostics.reset();
    TraceDiagnostics.frameBegin(name);
    final watch = Stopwatch()..start();
    for (var i = 0; i < reps; i++) {
      locus.recompute();
    }
    watch.stop();
    TraceDiagnostics.frameEnd();
    final frame = TraceDiagnostics.history.single;
    final solves = frame[TraceCounter.chainSolves] / reps;
    final ms = watch.elapsedMicroseconds / 1000 / reps;
    print(
      '  $name: ${ms.toStringAsFixed(2)} ms/sweep  '
      '${solves.round()} solves  '
      '${(ms * 1000 / solves).toStringAsFixed(2)} us/solve',
    );
  }
}
